/**
 * Pure tests for the crq repair binding policy.
 *
 * The oracle fixture is generated by `apps/crq-python/repair_prepare_vectors.py`
 * from the PRODUCTION Python `bounded.py` and `prepare_current_job` with faked
 * effects. These tests pin the policy against those oracle bytes and against
 * explicit Python semantics (code-point lengths, `str.strip`, lossless
 * numbers, `PurePosixPath` normalisation). No process, filesystem write, clock
 * or network participates.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, test } from 'vitest';
import {
  checkSha,
  dispatchInstructionsRefusal,
  findingDigest,
  legacyPythonResultRefusal,
  preparedIdentity,
  proposedPreparedJob,
  proposedRunRecord,
  pythonLength,
  pythonStrip,
  pythonTruthy,
  severityRepairable,
  sourcePath,
  typedFixFindingResultRefusal,
  validateEvidenceBinding,
  validateInstructions,
} from '../../../src/policy/crq/repairBinding.js';
import {
  JsonNumber,
  JsonObject,
  parseJsonValue,
  type JsonValue,
} from '../../../src/policy/crq/jsonValue.js';
import { atomicJsonText } from '../../../src/policy/crq/pythonJson.js';
import type { FixFindingBinding } from '../../../src/ops/review/fixFinding.js';

const FIXTURE_URL = new URL(
  '../../../apps/crq-python/fixtures/repair-prepare/cases.json',
  import.meta.url,
);
const fixture = asObject(parseJsonValue(readFileSync(FIXTURE_URL, 'utf8')));

function asObject(value: JsonValue | undefined): JsonObject {
  if (!(value instanceof JsonObject)) throw new Error('expected a JSON object');
  return value;
}

function asArray(value: JsonValue | undefined): JsonValue[] {
  if (!Array.isArray(value)) throw new Error('expected a JSON array');
  return value;
}

function asString(value: JsonValue | undefined): string {
  if (typeof value !== 'string') throw new Error('expected a JSON string');
  return value;
}

function asBoolean(value: JsonValue | undefined): boolean {
  if (typeof value !== 'boolean') throw new Error('expected a JSON boolean');
  return value;
}

function prepareCase(name: string): JsonObject {
  const found = asArray(fixture.get('prepare_cases')).find(
    (candidate) => asObject(candidate).get('name') === name,
  );
  return asObject(found);
}

function harvestCase(name: string): JsonObject {
  const found = asArray(fixture.get('harvest_cases')).find(
    (candidate) => asObject(candidate).get('name') === name,
  );
  return asObject(found);
}

function prepareInput(caseName: string): JsonObject {
  return asObject(prepareCase(caseName).get('input'));
}

describe('source_path matches PurePosixPath and the Python oracle', () => {
  for (const entry of asArray(fixture.get('path_cases')).map(asObject)) {
    const input = asString(entry.get('input'));
    const expected = asBoolean(entry.get('ok'))
      ? { ok: true as const, path: asString(entry.get('path')) }
      : { ok: false as const, refusal: 'finding-path-invalid' as const };
    test(`path ${JSON.stringify(input)}`, () => {
      expect(sourcePath(new JsonObject([['path', input]]))).toEqual(expected);
    });
  }
});

describe('sha and severity grammar', () => {
  test('check_sha', () => {
    expect(checkSha('a'.repeat(40))).toBe(true);
    expect(checkSha('A'.repeat(40))).toBe(false);
    expect(checkSha('a'.repeat(39))).toBe(false);
    expect(checkSha('a'.repeat(41))).toBe(false);
    expect(checkSha(123)).toBe(false);
  });

  const finding = (severity: string): JsonObject => new JsonObject([['severity', severity]]);
  test('repairable severity', () => {
    for (const severity of ['critical', 'major']) {
      expect(severityRepairable(new JsonObject([['finding', finding(severity)]]))).toBe(true);
    }
    expect(
      severityRepairable(
        new JsonObject([
          ['finding', finding('minor')],
          ['canonical_finding_id', 'f'.repeat(64)],
        ]),
      ),
    ).toBe(true);
    expect(severityRepairable(new JsonObject([['finding', finding('minor')]]))).toBe(false);
    expect(
      severityRepairable(
        new JsonObject([
          ['finding', finding('minor')],
          ['canonical_finding_id', 'F'.repeat(64)],
        ]),
      ),
    ).toBe(false);
    for (const severity of ['trivial', 'info', 'none']) {
      expect(severityRepairable(new JsonObject([['finding', finding(severity)]]))).toBe(false);
    }
  });
});

describe('Python text semantics', () => {
  test('str.strip uses Python whitespace, not JavaScript trim', () => {
    expect(pythonStrip('\u001c\u0085\u00a0x\u3000')).toBe('x');
    // U+FEFF is JavaScript whitespace but NOT Python str.isspace().
    expect(pythonStrip('\ufeffx\ufeff')).toBe('\ufeffx\ufeff');
    expect(pythonStrip('\u180ex\u180e')).toBe('\u180ex\u180e');
  });

  test('len counts code points', () => {
    expect(pythonLength('\u{1f642}')).toBe(1);
    expect('\u{1f642}'.length).toBe(2);
    expect(pythonLength('\u{1f642}'.repeat(2000))).toBe(2000);
  });

  test('instructions keep Python validation; dispatch refuses UTF-16 overflow', () => {
    const evidence = (value: JsonValue): JsonObject =>
      new JsonObject([['fix_instructions', value]]);
    expect(validateInstructions(new JsonObject([]))).toEqual({ ok: true });

    const bmp = 'x'.repeat(2000);
    expect(validateInstructions(evidence(bmp))).toEqual({ ok: true, instructions: bmp });
    expect(dispatchInstructionsRefusal(bmp)).toBeUndefined();

    const nonBmp = '\u{1f642}'.repeat(2000);
    expect(validateInstructions(evidence(nonBmp))).toEqual({
      ok: true,
      instructions: nonBmp,
    });
    expect(dispatchInstructionsRefusal(nonBmp)).toBe('instructions-dispatch-incompatible');

    for (const invalid of ['x'.repeat(2001), '', ' \u001c ', 'bad\u0000text', JsonNumber.int(42)]) {
      expect(validateInstructions(evidence(invalid))).toEqual({
        ok: false,
        refusal: 'instructions-invalid',
      });
    }
    expect(dispatchInstructionsRefusal('')).toBe('instructions-dispatch-incompatible');
    expect(dispatchInstructionsRefusal('bad\u0000text')).toBe('instructions-dispatch-incompatible');
  });
});

describe('pythonTruthy', () => {
  test('mirrors Python bool()', () => {
    const falsy: JsonValue[] = [
      null,
      false,
      JsonNumber.int(0),
      JsonNumber.float(0, '0.0'),
      '',
      [],
      new JsonObject([]),
    ];
    for (const value of falsy) expect(pythonTruthy(value)).toBe(false);
    const truthy: JsonValue[] = [
      true,
      JsonNumber.int(1),
      JsonNumber.float(0.5),
      'x',
      [null],
      new JsonObject([['a', JsonNumber.int(1)]]),
    ];
    for (const value of truthy) expect(pythonTruthy(value)).toBe(true);
    expect(pythonTruthy(JsonNumber.float(Number.NaN))).toBe(true);
  });
});

describe('lossless digests and proposal bytes match the Python oracle', () => {
  test('finding and evidence digests include extras and numeric lexemes', () => {
    for (const name of [
      'major-no-instructions',
      'lossless-extras',
      'non-bmp-reviewer-and-instructions',
    ]) {
      const input = prepareInput(name);
      const expected = prepareCase(name);
      const oldJob = asObject(parseJsonValue(asString(input.get('old_job_json'))));
      const evidence = asObject(parseJsonValue(asString(input.get('evidence_json'))));
      const finding = oldJob.get('finding');
      if (finding === undefined) throw new Error('fixture finding missing');
      expect(findingDigest(finding)).toBe(asString(expected.get('finding_sha256')));
      const identity = preparedIdentity({
        oldJobId: asString(input.get('old_job_id')),
        sourceSha: asString(input.get('source_sha')),
        evidence,
        ...(asBoolean(input.get('preserve_worktree')) ? { preserveWorktree: true } : {}),
      });
      expect(identity.run).toBe(asString(expected.get('run')));
      expect(identity.jobId).toBe(asString(expected.get('job_id')));
      expect(identity.revalidationSha256).toBe(asString(expected.get('revalidation_sha256')));
    }
  });

  test('proposed job and record reproduce the oracle bytes without mutating input', () => {
    const input = prepareInput('major-no-instructions');
    const expected = prepareCase('major-no-instructions');
    const oldJobText = asString(input.get('old_job_json'));
    const evidenceText = asString(input.get('evidence_json'));
    const oldJob = asObject(parseJsonValue(oldJobText));
    const evidence = asObject(parseJsonValue(evidenceText));
    const identity = preparedIdentity({
      oldJobId: asString(input.get('old_job_id')),
      sourceSha: asString(input.get('source_sha')),
      evidence,
    });
    const finding = oldJob.get('finding');
    if (finding === undefined) throw new Error('fixture finding missing');
    const job = proposedPreparedJob({
      oldJob,
      oldJobId: asString(input.get('old_job_id')),
      sourceSha: asString(input.get('source_sha')),
      evidence,
      findingSha256: findingDigest(finding),
      round: 1,
      run: identity.run,
      jobId: identity.jobId,
    });
    expect(atomicJsonText(job)).toBe(asString(expected.get('job_bytes')));
    const record = proposedRunRecord({
      jobId: identity.jobId,
      sourceSha: asString(input.get('source_sha')),
      round: 1,
      originJobId: asString(input.get('old_job_id')),
      revalidationSha256: identity.revalidationSha256,
    });
    expect(atomicJsonText(record)).toBe(asString(expected.get('record_bytes')));
    // Inputs are immutable.
    expect(atomicJsonText(oldJob)).toBe(oldJobText);
    expect(atomicJsonText(evidence)).toBe(evidenceText);
  });

  test('the 1 vs 1.0 distinction reaches identity', () => {
    const intEvidence = asObject(parseJsonValue('{"x":1}'));
    const floatEvidence = asObject(parseJsonValue('{"x":1.0}'));
    const identity = (evidence: JsonObject): string =>
      preparedIdentity({ oldJobId: 'j', sourceSha: 'a'.repeat(40), evidence }).revalidationSha256;
    expect(identity(intEvidence)).not.toBe(identity(floatEvidence));
  });
});

describe('validateEvidenceBinding refusal order and codes', () => {
  const input = prepareInput('major-no-instructions');
  const oldJob = asObject(parseJsonValue(asString(input.get('old_job_json'))));
  const evidence = asObject(parseJsonValue(asString(input.get('evidence_json'))));
  const sourceSha = asString(input.get('source_sha'));
  const blob = 'c'.repeat(40);
  const withEvidence = (key: string, value: JsonValue): JsonObject =>
    new JsonObject(
      evidence.entries.map(([name, current]) => [name, name === key ? value : current]),
    );

  test('accepts the oracle binding', () => {
    expect(
      validateEvidenceBinding({
        oldJob,
        sourceSha,
        evidence,
        observed: { currentTip: sourceSha, blobOid: blob },
      }),
    ).toBeUndefined();
  });

  test('rejects each field with its typed code', () => {
    const cases: Array<[string, JsonValue, string]> = [
      ['source_sha', 'd'.repeat(40), 'evidence-source-sha-mismatch'],
      ['finding_sha256', 'd'.repeat(64), 'finding-digest-mismatch'],
      ['verdict', 'superseded', 'verdict-not-still-valid'],
      ['reviewer', '   ', 'evidence-text-invalid'],
      ['reviewer', JsonNumber.int(7), 'evidence-text-invalid'],
      ['reason', 'x'.repeat(4001), 'evidence-text-invalid'],
    ];
    for (const [key, value, refusal] of cases) {
      expect(
        validateEvidenceBinding({
          oldJob,
          sourceSha,
          evidence: withEvidence(key, value),
          observed: { currentTip: sourceSha, blobOid: blob },
        }),
      ).toBe(refusal);
    }
    expect(
      validateEvidenceBinding({
        oldJob,
        sourceSha: 'A'.repeat(40),
        evidence,
        observed: { currentTip: sourceSha, blobOid: blob },
      }),
    ).toBe('source-sha-invalid');
    expect(
      validateEvidenceBinding({
        oldJob,
        sourceSha,
        evidence,
        observed: { currentTip: 'd'.repeat(40), blobOid: blob },
      }),
    ).toBe('source-not-current-tip');
    expect(
      validateEvidenceBinding({
        oldJob,
        sourceSha,
        evidence,
        observed: { currentTip: sourceSha, blobOid: 'd'.repeat(40) },
      }),
    ).toBe('source-blob-mismatch');
  });
});

describe('harvest checks', () => {
  const preparedRow = harvestCase('legacy-match');
  const prepared = asObject(parseJsonValue(asString(preparedRow.get('prepared_json'))));
  const result = parseJsonValue(asString(preparedRow.get('result_json')));

  test('legacy parity: identity then binding', () => {
    expect(
      legacyPythonResultRefusal({
        prepared,
        result,
        allowMissingPreparedSourceSha: false,
      }),
    ).toBeUndefined();
    const withoutSource = new JsonObject(
      prepared.entries.map(([key, value]) => [key, key === 'source_sha' ? null : value]),
    );
    expect(
      legacyPythonResultRefusal({
        prepared: withoutSource,
        result,
        allowMissingPreparedSourceSha: false,
      }),
    ).toBe('legacy-source-sha-missing');
    expect(
      legacyPythonResultRefusal({
        prepared: withoutSource,
        result,
        allowMissingPreparedSourceSha: true,
      }),
    ).toBeUndefined();
    const mismatched = asObject(result);
    for (const key of ['job', 'item']) {
      const changed = new JsonObject(
        mismatched.entries.map(([name, value]) => [name, name === key ? 'crq-other-F1' : value]),
      );
      expect(
        legacyPythonResultRefusal({
          prepared,
          result: changed,
          allowMissingPreparedSourceSha: false,
        }),
      ).toBe('result-identity-mismatch');
    }
    for (const key of ['source_sha', 'finding_sha256', 'origin_job']) {
      const changed = new JsonObject(
        mismatched.entries.map(([name, value]) => [name, name === key ? 'd'.repeat(40) : value]),
      );
      expect(
        legacyPythonResultRefusal({
          prepared,
          result: changed,
          allowMissingPreparedSourceSha: false,
        }),
      ).toBe('result-binding-mismatch');
    }
    expect(
      legacyPythonResultRefusal({
        prepared,
        result: [],
        allowMissingPreparedSourceSha: false,
      }),
    ).toBe('result-not-object');
  });

  test('typed fixFinding artifact unwraps the real OpResult envelope', () => {
    const binding: FixFindingBinding = {
      job: 'crq-revalidated-x-F1',
      sourceSha: 'a'.repeat(40),
      sourceBlobSha: 'c'.repeat(40),
      findingSha256: 'f'.repeat(64),
      repairBase: 'a'.repeat(40),
    };
    const artifact = (echo: JsonValue): JsonValue =>
      new JsonObject([
        ['status', 'ok'],
        ['value', new JsonObject([['binding', echo]])],
      ]);
    const echo = new JsonObject([
      ['job', binding.job],
      ['sourceSha', binding.sourceSha],
      ['sourceBlobSha', binding.sourceBlobSha],
      ['findingSha256', binding.findingSha256],
      ['repairBase', binding.repairBase],
    ]);
    expect(typedFixFindingResultRefusal({ prepared: binding, artifact: artifact(echo) })).toBe(
      undefined,
    );
    expect(
      typedFixFindingResultRefusal({
        prepared: binding,
        artifact: new JsonObject([['status', 'ok']]),
      }),
    ).toBe('fixfinding-result-envelope-invalid');
    expect(
      typedFixFindingResultRefusal({
        prepared: binding,
        artifact: new JsonObject([
          ['status', 'ok'],
          ['value', new JsonObject([['binding', 'not-an-object']])],
        ]),
      }),
    ).toBe('fixfinding-result-binding-missing');
    for (const status of ['failed', 'needs-human', 'budget-exhausted', 'indeterminate']) {
      expect(
        typedFixFindingResultRefusal({
          prepared: binding,
          artifact: new JsonObject([['status', status]]),
        }),
      ).toBe('fixfinding-result-not-ok');
    }
    for (const artifactValue of [
      new JsonObject([]),
      new JsonObject([['status', JsonNumber.int(1)]]),
      new JsonObject([['status', 'unknown']]),
      new JsonObject([
        ['status', 'ok'],
        ['value', []],
      ]),
    ]) {
      expect(typedFixFindingResultRefusal({ prepared: binding, artifact: artifactValue })).toBe(
        'fixfinding-result-envelope-invalid',
      );
    }
    expect(typedFixFindingResultRefusal({ prepared: binding, artifact: [] })).toBe(
      'result-not-object',
    );
    for (const key of ['job', 'sourceSha', 'sourceBlobSha', 'findingSha256', 'repairBase']) {
      const missing = new JsonObject(echo.entries.filter(([name]) => name !== key));
      expect(typedFixFindingResultRefusal({ prepared: binding, artifact: artifact(missing) })).toBe(
        'fixfinding-result-binding-missing',
      );
      const wrong = new JsonObject(
        echo.entries.map(([name, value]) => [name, name === key ? 'wrong' : value]),
      );
      expect(typedFixFindingResultRefusal({ prepared: binding, artifact: artifact(wrong) })).toBe(
        'fixfinding-result-binding-mismatch',
      );
    }
  });
});
